{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C43"],
      "claim": "Linezolid, the closest analogue sharing the oxazolidinone core and an N-aryl morpholine-type substituent, has essentially 100% absolute oral bioavailability in humans, directly supporting a high-F prediction for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "The structurally close oxazolidinone YH4808 had low absolute bioavailability (10.1%) in subjects, a contradictory result; however, its thiomorpholine and fluoro substituents differ from the query's morpholinone and chlorothiophene carboxamide, reducing transferability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C28"],
      "claim": "Delpazolid, another oxazolidinone, showed 99.75% absolute oral bioavailability in healthy volunteers after an 800 mg oral dose, reinforcing that oxazolidinones can be essentially completely absorbed.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is an oxazolidinone closely related to linezolid, which has essentially complete oral bioavailability in humans, and other oxazolidinones such as delpazolid also exceed the 20% threshold. The only close low-F analogue (YH4808) differs by a thiomorpholine moiety likely responsible for its poor F, so the balance of transferable evidence supports high oral bioavailability (F >= 20%).",
  "evidence_gaps": [
    "No direct fed-state bioavailability data are available for the query or exact analogues; extrapolation relies on fasted or unspecified conditions.",
    "No human PK data exist for the exact query molecule.",
    "The mechanism underlying the low F of YH4808 (poor absorption vs first-pass metabolism) is not specified, limiting assessment of its transferability.",
    "Food effects on absorption of this oxazolidinone series are not directly evidenced."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

